"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["22998"],{86238(a){a.exports=JSON.parse('{"id":"F403","slug":"bs-pde-check","name":"Black-Scholes PDE Check","subject":"Quantitative Finance","section":"Quant","topic":"Deriving the Black-Scholes PDE","level":"Intermediate","aliases":["Black Scholes partial differential equation","deriving Black Scholes","delta hedged portfolio return"],"formula":{"latex":"\\\\frac{\\\\partial V}{\\\\partial t}+rS\\\\frac{\\\\partial V}{\\\\partial S}+\\\\tfrac{1}{2}\\\\sigma^{2}S^{2}\\\\frac{\\\\partial^{2}V}{\\\\partial S^{2}}-rV=0","also":[],"text":"Theta + r x S x Delta + 0.5 x sigma^2 x S^2 x Gamma - r x V = 0 for any option price V that follows from Black-Scholes"},"symbols":[{"symbol":"V","meaning":"Option value","unit":"money"},{"symbol":"Theta","meaning":"Rate of change of V as time passes (negative for a long option)","unit":"money per year"},{"symbol":"Delta, Gamma","meaning":"First and second derivative of V with respect to the stock price","unit":"number"},{"symbol":"r","meaning":"Risk-free rate","unit":"per year"}],"when_to_use":"Use it to see how Black-Scholes is derived. A portfolio long one option and short Delta shares has no random shocks, so by no-arbitrage it must earn the risk-free rate. That condition gives this equation. The check shows that the formula\'s price satisfies it: the terms add to zero.","worked_example":{"problem":"A call has a stock price of 100, strike of 100, rate of 5%, volatility of 20% and one year to expiry. Check that the Black-Scholes price satisfies the equation.","inputs":{"s":100,"k":100,"r":5,"sig":20,"t":1},"steps":[{"label":"d1","working":"(ln(100 / 100)+(0.05+0.2^2 / 2) x 1) / (0.2 x sqrt(1))","value":"0.3500"},{"label":"d2","working":"d1-0.2 x sqrt(1)","value":"0.1500"},{"label":"Call value V","working":null,"value":"10.4506"},{"label":"Delta = N(d1)","working":null,"value":"0.6368"},{"label":"Gamma = pdf(d1) / (S sigma sqrt(T))","working":null,"value":"0.01876"},{"label":"Theta = -S pdf(d1) sigma / (2 sqrt(T)) - r K e^(-rT) N(d2)","working":null,"value":"-6.4140"},{"label":"Theta + r S Delta + 0.5 sigma^2 S^2 Gamma - r V","working":"-6.41403+0.05 x 100 x 0.636831+0.5 x 0.2^2 x 100^2 x 0.018762-0.05 x 10.4506","value":"-0.00000000"}],"answer":"The call is worth 10.4506 with delta 0.6368, gamma 0.01876 and theta -6.4140 per year. The four terms sum to -0.00000000, which is zero up to rounding, so the price solves the equation. Holding the option and shorting delta shares earns exactly the risk-free rate."},"calculator":{"available":true,"inputs":[{"id":"s","label":"Stock price","unit":"money","type":"number","default":100,"hint":""},{"id":"k","label":"Strike","unit":"money","type":"number","default":100,"hint":""},{"id":"r","label":"Risk-free rate","unit":"%","type":"number","default":5,"hint":""},{"id":"sig","label":"Volatility","unit":"%","type":"number","default":20,"hint":""},{"id":"t","label":"Years to expiry","unit":"years","type":"number","default":1,"hint":"","min":0.1}],"checks":[],"steps":[{"id":"d1","label":"d1","expr":"(ln(s/k)+(r+sig^2/2)*t)/(sig*sqrt(t))","format":"num4"},{"id":"d2","label":"d2","expr":"d1-sig*sqrt(t)","format":"num4"},{"id":"v","label":"Call value V","expr":"s*normcdf(d1)-k*exp(-r*t)*normcdf(d2)","format":"num4"},{"id":"delta","label":"Delta = N(d1)","expr":"normcdf(d1)","format":"num4"},{"id":"gamma","label":"Gamma = pdf(d1) / (S sigma sqrt(T))","expr":"normpdf(d1)/(s*sig*sqrt(t))","format":"num5"},{"id":"theta","label":"Theta = -S pdf(d1) sigma / (2 sqrt(T)) - r K e^(-rT) N(d2)","expr":"-s*normpdf(d1)*sig/(2*sqrt(t))-r*k*exp(-r*t)*normcdf(d2)","format":"num4"},{"id":"resid","label":"Theta + r S Delta + 0.5 sigma^2 S^2 Gamma - r V","expr":"theta+r*s*delta+0.5*sig^2*s^2*gamma-r*v","format":"num8"}],"results":["v","resid"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"v":10.450583572185565,"delta":0.6368306511756191,"gamma":1.8762017345846895e-2,"theta":-6.414027546438197,"resid":0}},"finder":{"finds":"That a Black-Scholes price satisfies the pricing equation","needs":"Option inputs"},"related":[{"slug":"black-scholes-merton","name":"Black-Scholes-Merton Option Price"},{"slug":"option-greeks","name":"Option Greeks: Delta, Gamma, Vega, Theta, Rho"},{"slug":"risk-neutral-pricing","name":"Risk-Neutral Probability and Pricing"}],"related_ids":["F331","F332","F404"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mfrac><mrow><mi mathvariant=\\"normal\\">\u2202</mi><mi>V</mi></mrow><mrow><mi mathvariant=\\"normal\\">\u2202</mi><mi>t</mi></mrow></mfrac><mo>+</mo><mi>r</mi><mi>S</mi><mfrac><mrow><mi mathvariant=\\"normal\\">\u2202</mi><mi>V</mi></mrow><mrow><mi mathvariant=\\"normal\\">\u2202</mi><mi>S</mi></mrow></mfrac><mo>+</mo><mstyle displaystyle=\\"false\\" scriptlevel=\\"0\\"><mfrac><mn>1</mn><mn>2</mn></mfrac></mstyle><msup><mi>\u03C3</mi><mn>2</mn></msup><msup><mi>S</mi><mn>2</mn></msup><mfrac><mrow><msup><mi mathvariant=\\"normal\\">\u2202</mi><mn>2</mn></msup><mi>V</mi></mrow><mrow><mi mathvariant=\\"normal\\">\u2202</mi><msup><mi>S</mi><mn>2</mn></msup></mrow></mfrac><mo>\u2212</mo><mi>r</mi><mi>V</mi><mo>=</mo><mn>0</mn></mrow><annotation encoding=\\"application/x-tex\\">\\\\frac{\\\\partial V}{\\\\partial t}+rS\\\\frac{\\\\partial V}{\\\\partial S}+\\\\tfrac{1}{2}\\\\sigma^{2}S^{2}\\\\frac{\\\\partial^{2}V}{\\\\partial S^{2}}-rV=0</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"black-litterman-one-asset","name":"Black-Litterman: Blending a View with Equilibrium (One Asset)"},"next":{"slug":"black-scholes-merton","name":"Black-Scholes-Merton Option Price"},"lesson":null,"total":522}')}}]);